query ListAddOnPlans ($addOnType: AddOnType!) {
	addOnPlans(type: $addOnType) {
		nodes {
			id
			description
			displayName
			maxDataSize
			pricePerMonth
		}
	}
}

query ListAddOns ($addOnType: AddOnType) {
	addOns(type: $addOnType) {
		nodes {
			id
			name
			addOnPlan {
				displayName
				description
			}
			privateIp
			primaryRegion
			readRegions
			options
			metadata
			organization {
				id
				slug
			}
		}
	}
}

query ListOrganizationAddOns ($orgSlug: String!, $addOnType: AddOnType) {
	organization(slug: $orgSlug) {
		addOns(type: $addOnType) {
			nodes {
				id
				name
				addOnPlan {
					displayName
					description
				}
				privateIp
				primaryRegion
				readRegions
				options
				metadata
			}
		}
	}
}

mutation LogOut {
	logOut(input: {}) {
		ok
	}
}

mutation ResetAddOnPassword ($name: String!) {
	resetAddOnPassword(input: {name:$name}) {
		addOn {
			publicUrl
		}
	}
}

mutation SetNomadVMCount ($input: SetVMCountInput!) {
	setVmCount(input: $input) {
		taskGroupCounts {
			name
			count
		}
		warnings
	}
}

mutation SetSecrets ($input: SetSecretsInput!) {
	setSecrets(input: $input) {
		release {
			id
			version
			reason
			description
			user {
				id
				email
				name
			}
			evaluationId
			createdAt
		}
	}
}

mutation UpdateAddOn ($addOnId: ID!, $planId: ID!, $readRegions: [String!]!, $options: JSON!, $metadata: JSON!) {
	updateAddOn(input: {addOnId:$addOnId,planId:$planId,readRegions:$readRegions,options:$options,metadata:$metadata}) {
		addOn {
			id
		}
	}
}

mutation UpdateRedisAddOn ($addOnId: ID!, $planId: ID!, $readRegions: [String!]!, $options: JSON!, $metadata: JSON!, $prodPack: Boolean) {
	updateAddOn(input: {addOnId:$addOnId,planId:$planId,readRegions:$readRegions,options:$options,metadata:$metadata,prodPack:$prodPack}) {
		addOn {
			id
		}
	}
}

